export const ERROR_INSUFFICIENT_BUFFER = 122;

export class Win32Error extends Error {
  constructor(api, code, detail) {
    super(`${api} failed (Win32 ${code})${detail ? `: ${detail}` : ""}`);
    this.name = "Win32Error";
    this.api = api;
    this.win32Code = code;
  }
}

function unavailable() {
  throw new Error("Windows process APIs are unavailable on Android");
}

export function loadWin32ProcessBindings() {
  unavailable();
}

export function probeCurrentTokenJobSupport() {
  return false;
}

export const closeHandleChecked = unavailable;
export const isJobEmpty = unavailable;
export const pollProcessExit = unavailable;
export const spawnCurrentTokenJobProcess = unavailable;
export const terminateJob = unavailable;
export const allocPtrSlot = unavailable;
export const allocUint32 = unavailable;
export const decodePtr = unavailable;
export const decodeUint32 = unavailable;
export const drainPipe = unavailable;
export const extendWin32ProcessBindings = unavailable;
export const isNullPtr = (value) => value === null || value === undefined || value === 0n;
export const spawnInheritedJobProcess = unavailable;
export const spawnPipedProcess = unavailable;
export const throwLastError = unavailable;
export const throwWin32 = unavailable;
export const waitForProcessExit = unavailable;
